import logging
from pathlib import Path

import yaml

logger = logging.getLogger("aichat_sdk")

SKILLS_DIR = Path("~/.agents/skills").expanduser()


def _parse_skill_frontmatter(skill_file: Path) -> dict[str, str] | None:
    content = skill_file.read_text(encoding="utf-8")
    if not content.startswith("---"):
        return None

    end = content.find("---", 3)
    if end == -1:
        return None

    frontmatter = yaml.safe_load(content[3:end])
    if not isinstance(frontmatter, dict):
        return None

    name = frontmatter.get("name")
    description = frontmatter.get("description")
    if not name or not description:
        return None

    return {"name": name, "description": description, "location": str(skill_file)}


def load_skills() -> list[dict[str, str]]:
    """SKILLS_DIR 下所有 SKILL.md 的 name/description/location（SKILL.md 绝对路径）。"""
    skills: list[dict[str, str]] = []
    for skill_file in sorted(SKILLS_DIR.glob("**/SKILL.md")):
        parsed = _parse_skill_frontmatter(skill_file)
        if parsed:
            skills.append(parsed)
    return skills


def select_skills(names: list[str] | None) -> list[dict[str, str]]:
    """按名字挑技能：None 取全部，[] 一个不要；名字对不上的告警跳过。"""
    skills = load_skills()
    if names is None:
        return skills
    wanted = set(names)
    known = {skill["name"] for skill in skills}
    for name in wanted - known:
        logger.warning(f"skill '{name}' not found under {SKILLS_DIR}, ignored")
    return [skill for skill in skills if skill["name"] in wanted]


def find_skill_dir(name: str) -> Path | None:
    """按 frontmatter 里的 name 找技能目录（SKILL.md 所在目录）。"""
    for skill in load_skills():
        if skill["name"] == name:
            return Path(skill["location"]).parent
    return None
