}

function skillInstallButtons() {
  $("#skill-upload").disabled = $("#skill-run").disabled = skillInstalling || skillCommandRunning;
}

function renderSkillInstall(state) {
  if (!state) return;
  const sig = JSON.stringify(state);
  if (sig === skillInstallSig) return;
  skillInstallSig = sig;
  skillCommandRunning = state.running;
  skillInstallButtons();
  const output = $("#skill-install-output");
  if (state.output) {
    output.hidden = false;
    output.textContent = state.output;
    output.scrollTop = output.scrollHeight;
  }
  if (state.running && !state.output) {
    output.hidden = true;
    output.textContent = "";
  }
  if (state.running) skillInstallNote("命令安装中…", true);
  else if (state.error) skillInstallNote(state.error, false);
}

async function installSkill(mode) {
  if (skillInstalling || skillCommandRunning) return;
  let url, options;
  if (mode === "upload") {
    const file = $("#skill-file").files[0];
    if (!file) return skillInstallNote("请先选择 ZIP 技能包或 SKILL.md", false);
    if (file.name !== "SKILL.md" && !file.name.toLowerCase().endsWith(".zip")) return skillInstallNote("请选择 ZIP 技能包或 SKILL.md", false);
    if (!file.size || file.size > 10 * 1024 * 1024) return skillInstallNote("文件不能为空且不能超过 10 MB", false);
