    const res = await fetch(url, options);
    const data = await res.json();
    if (data.output) {
      $("#skill-install-output").textContent = data.output;
      $("#skill-install-output").hidden = false;
    }
    if (!res.ok || !data.ok) throw new Error(data.error || "安装失败");
    // 安装只刷新技能清单，保留用户尚未保存的表单和技能开关。
    const toggles = collectSkills();
    renderSkills(data.skills || [], data.skills_dir);
    for (const box of document.querySelectorAll("#skill-rows .mcp-enabled")) {
      if (Object.hasOwn(toggles, box.dataset.skill)) {
        box.checked = toggles[box.dataset.skill];
        box.dispatchEvent(new Event("change"));
      }
    }
    $("#skill-search").value = "";
    filterSkills();
    if (mode === "upload") $("#skill-file").value = "";
    const names = data.skill ? [data.skill.name] : data.installed;
    skillInstallNote(names?.length ? "已安装 " + names.join("、") + "，保存并重启后生效" : "命令执行完成，未发现新增技能。请查看输出，并确认安装到了 " + data.skills_dir, true);
  } catch (e) {
    skillInstallNote(e.message || String(e), false);
  } finally {
    skillInstalling = false;
    skillCommandRunning = false;
    skillInstallButtons();
