function skillFileError(file) {
  if (!file) return "请先选择 ZIP 技能包或 SKILL.md";
  if (file.name !== "SKILL.md" && !file.name.toLowerCase().endsWith(".zip")) return "请选择 ZIP 技能包或 SKILL.md";
