  return "";
}

function skillInstallNote(text, ok) {
  $("#skill-install-note").textContent = text;
  $("#skill-install-note").className = "note " + (ok ? "ok" : "err");
}

function skillInstallButtons() {
  const installing = skillInstalling || skillCommandRunning;
  $("#skill-installer").setAttribute("aria-busy", String(installing));
  $("#skill-upload").disabled = installing || !!skillFileError($("#skill-file").files[0]);
  $("#skill-run").disabled = installing || !$("#skill-command").value.trim();
  for (const id of ["skill-choose", "skill-file", "skill-command", "skill-lark", "skill-upload-tab", "skill-command-tab"]) $("#" + id).disabled = installing;
  $("#skill-upload").textContent = installing && skillInstallMode === "upload" ? "正在安装…" : "安装技能";
  $("#skill-run").textContent = installing && skillInstallMode === "command" ? "正在安装…" : "执行安装";
}

function renderSkillInstall(state) {
  if (!state) return;
  const sig = JSON.stringify(state);
  if (sig === skillInstallSig) return;
  skillInstallSig = sig;
  skillCommandRunning = state.running;
  if (state.running) setSkillInstallMode("command");
  skillInstallButtons();
  const output = $("#skill-install-output");
  if (state.output) {
    output.hidden = false;
    output.textContent = state.output;
    output.scrollTop = output.scrollHeight;
  }
  if (state.running && !state.output) {
    output.hidden = true;
    output.textContent = "";
  }
  if (state.running) skillInstallNote("命令安装中…", true);
  else if (state.error) skillInstallNote(state.error, false);
}

async function installSkill(mode) {
  if (skillInstalling || skillCommandRunning) return;
  let url, options;
  if (mode === "upload") {
    const file = $("#skill-file").files[0];
    const error = skillFileError(file);
    if (error) return skillInstallNote(error, false);
    url = "/api/skills/install?filename=" + encodeURIComponent(file.name);
    options = {method: "POST", headers: {"Content-Type": "application/octet-stream"}, body: file};
  } else {
    const command = $("#skill-command").value.trim();
    if (!command) return skillInstallNote("请输入安装命令", false);
    url = "/api/skills/command";
    options = {method: "POST", headers: {"Content-Type": "application/json"}, body: JSON.stringify({command})};
  }
  skillInstalling = true;
  skillInstallButtons();
  $("#skill-install-output").hidden = true;
  $("#skill-install-output").textContent = "";
  skillInstallNote(mode === "upload" ? "上传安装中…" : "命令安装中…", true);
  try {
    const res = await fetch(url, options);
    const data = await res.json();
    if (data.output) {
      $("#skill-install-output").textContent = data.output;
      $("#skill-install-output").hidden = false;
    }
    if (!res.ok || !data.ok) throw new Error(data.error || "安装失败");
    // 安装只刷新技能清单，保留用户尚未保存的表单和技能开关。
    const toggles = collectSkills();
    renderSkills(data.skills || [], data.skills_dir);
    for (const box of document.querySelectorAll("#skill-rows .mcp-enabled")) {
      if (Object.hasOwn(toggles, box.dataset.skill)) {
        box.checked = toggles[box.dataset.skill];
        box.dispatchEvent(new Event("change"));
      }
    }
    $("#skill-search").value = "";
    filterSkills();
    if (mode === "upload") {
      $("#skill-file").value = "";
      updateSkillFile();
    }
    const names = data.skill ? [data.skill.name] : data.installed;
    skillInstallNote(names?.length ? "已安装 " + names.join("、") + "，保存并重启后生效" : "命令执行完成，未发现新增技能。请查看输出，并确认安装到了 " + data.skills_dir, true);
  } catch (e) {
    skillInstallNote(e.message || String(e), false);
  } finally {
    skillInstalling = false;
    skillCommandRunning = false;
    skillInstallButtons();
  }
}

function collectSkills() {
  const boxes = document.querySelectorAll("#skill-rows .mcp-enabled");
  if (!boxes.length) return skillToggles;  // 行还没建出来（首次取状态前）就用配置里的值
  const map = {};
  for (const box of boxes) map[box.dataset.skill] = box.checked;
  return map;
}

