}

function filterSkills() {
  const query = $("#skill-search").hidden ? "" : $("#skill-search").value.trim().toLowerCase();
  const rows = document.querySelectorAll("#skill-rows .mcp-row");
  let shown = 0;
  for (const row of rows) {
    const hit = !query || row.dataset.search.includes(query);
